foreach([P,M,F,Q] as $f)if(!is_file($f))@file_put_contents($f,"[]\n");
function j(string $f):array{$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];}
function sj(string $f,array $x):bool{$l=fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$q=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);if($q===false||file_put_contents($t,$q,LOCK_EX)===false)return false;@chmod($t,0640);return rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function e(string $x):string{return htmlspecialchars($x,ENT_QUOTES,'UTF-8');}
function now():string{return date('Y-m-d H:i:s');}
function cfg():array{return array_merge(['commission_percent'=>30,'support_phone'=>'','support_whatsapp'=>'','sms_api_key'=>'','sms_from_number'=>''],j(S));}
function branch(string $id):?array{foreach(j(B) as $x)if((string)($x['id']??'')===$id)return $x;return null;}
function lead(string $id):?array{foreach(j(L) as $x)if((string)($x['id']??'')===$id)return $x;return null;}
function assignment(string $id):?array{foreach(j(A) as $x)if((string)($x['id']??'')===$id)return $x;return null;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];}
function cf():string{return '<input type="hidden" name="csrf" value="'.e(csrf()).'">';}
