function go(string $u):never{header('Location: '.$u);exit;}
function money($x):int{return max(0,(int)(preg_replace('/\D/','',(string)$x)??'0'));}
function pctFor(array $a):int{$v=(int)($a['commission_percent']??0);if($v<=0)$v=(int)(cfg()['commission_percent']??30);return max(0,min(100,$v));}
function normalizePhone(string $p):string{$p=preg_replace('/\D/','',$p)??'';if(str_starts_with($p,'09'))return '+98'.substr($p,1);if(str_starts_with($p,'98'))return '+'.$p;if(str_starts_with($p,'9')&&strlen($p)===10)return '+98'.$p;return $p;}
function baseurl():string{$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';$host=$_SERVER['HTTP_HOST']??'websaza.ir';return ($https?'https':'http').'://'.$host.'/namayandegi/finance.php';}
function sendSms(string $phone,string $message,string $paymentId):bool{$q=j(Q);$id='SMS'.bin2hex(random_bytes(5));$row=['id'=>$id,'payment_id'=>$paymentId,'phone'=>$phone,'message'=>$message,'status'=>'queued','created_at'=>now(),'sent_at'=>'','error'=>''];$c=cfg();$api=trim((string)($c['sms_api_key']??getenv('FARAZ_SMS_API_KEY')?:''));$from=trim((string)($c['sms_from_number']??getenv('FARAZ_SMS_FROM')?:''));if($api!==''&&$from!==''&&function_exists('curl_init')){$payload=['sending_type'=>'webservice','from_number'=>$from,'message'=>$message,'params'=>['recipients'=>[normalizePhone($phone)]]];$ch=curl_init('https://edge.ippanel.com/v1/api/send');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: '.$api],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE)]);$res=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=(string)curl_error($ch);curl_close($ch);if($res!==false&&$code>=200&&$code<300){$row['status']='sent';$row['sent_at']=now();}else{$row['status']='failed';$row['error']=$err?:('HTTP '.$code);}}
$q[]=$row;if(count($q)>10000)$q=array_slice($q,-10000);sj(Q,$q);return $row['status']==='sent';}
function summary(string $bid):array{$payments=array_values(array_filter(j(P),fn($x)=>(string)($x['branch_id']??'')===$bid&&($x['status']??'active')!=='void'));$gross=$branchShare=$companyShare=0;foreach($payments as $p){$gross+=(int)($p['amount']??0);$branchShare+=(int)($p['branch_share']??0);$companyShare+=(int)($p['company_share']??0);} $approved=0;$pending=0;foreach(j(M) as $r)if((string)($r['branch_id']??'')===$bid){if(($r['status']??'pending')==='approved')$approved+=(int)($r['amount']??0);elseif(($r['status']??'pending')==='pending')$pending+=(int)($r['amount']??0);}return ['gross'=>$gross,'branch_share'=>$branchShare,'company_share'=>$companyShare,'approved'=>$approved,'pending'=>$pending,'due'=>max(0,$companyShare-$approved)];}
function headx(string $title):void{echo '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><title>'.e($title).' | وب ساز</title><link rel="stylesheet" href="./style.css"><style>.finwrap{max-width:1180px;margin:0 auto;padding:24px 14px 90px}.finhead{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:18px}.finhead a{text-decoration:none}.finstats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.finstats>div,.fcard{background:#171c24;border:1px solid #303844;border-radius:16px;padding:14px}.finstats span{display:block;opacity:.72;font-size:12px}.finstats b{display:block;font-size:19px;margin-top:6px}.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fcard{margin-bottom:14px}.fcard h2{margin-top:0}.ftable{overflow:auto}.ftable table{width:100%;border-collapse:collapse;min-width:780px}.ftable th,.ftable td{padding:9px;border-bottom:1px solid #2b333d;text-align:right;font-size:12px}.status{padding:4px 8px;border-radius:999px;font-size:11px;font-weight:800}.ok2{background:#173b2a;color:#9ef0be}.warn2{background:#4b3a13;color:#ffe08a}.bad2{background:#491f25;color:#ffb0b7}.publicbox{max-width:620px;margin:60px auto;padding:18px}.choice{display:grid;grid-template-columns:1fr 1fr;gap:10px}.muted2{opacity:.7;font-size:12px;line-height:1.8}@media(max-width:760px){.finstats,.fgrid{grid-template-columns:1fr 1fr}.choice{grid-template-columns:1fr}.finhead{align-items:flex-start;flex-direction:column}}@media(max-width:420px){.finstats{grid-template-columns:1fr 1fr}}</style></head><body>';}
function foot():void{echo '</body></html>';}

if(isset($_GET['verify'])){$tok=(string)$_GET['verify'];$pay=null;foreach(j(P) as $x)if(hash_equals((string)($x['verify_token']??''),$tok)){$pay=$x;break;}headx('تأیید دریافت وجه');echo '<main class="publicbox"><div class="fcard">';if(!$pay){echo '<h2>لینک معتبر نیست</h2><p>این لینک پیدا نشد یا منقضی شده است.</p>';foot();exit;}$ld=lead((string)$pay['lead_id']);echo '<h2>تأیید دریافت وجه</h2><p>برای '.e((string)($ld['business']??$ld['name']??'سفارش شما')).' مبلغ <b>'.number_format((int)$pay['amount']).' تومان</b> بابت <b>'.e((string)$pay['purpose']).'</b> ثبت شده است.</p>';if(!empty($pay['description']))echo '<p class="muted2">'.e((string)$pay['description']).'</p>';$existing=null;foreach(j(F) as $x)if((string)($x['payment_id']??'')===(string)$pay['id']){$existing=$x;break;}if($existing){echo '<div class="alert ok">پاسخ شما قبلاً ثبت شده است: '.(($existing['answer']??'')==='ok'?'مبلغ و عنوان مورد تأیید است.':'مغایرت گزارش شده است.').'</div>';}else{echo '<form method="post" class="form">'.cf().'<input type="hidden" name="action" value="customer_confirm"><input type="hidden" name="token" value="'.e($tok).'"><div class="choice"><label><input type="radio" name="answer" value="ok" required> مبلغ و عنوان درست است</label><label><input type="radio" name="answer" value="dispute" required> مبلغ/عنوان مغایرت دارد</label></div><label>مبلغی که واقعاً پرداخت کرده‌اید (در صورت مغایرت)<input inputmode="numeric" name="actual_amount"></label><label>توضیح شما<textarea name="note" rows="3" placeholder="مثلاً مبلغ بیشتر گرفته شده یا عنوان خدمت متفاوت بوده"></textarea></label><button class="btn lime">ثبت پاسخ</button></form>';} $c=cfg();$sp=(string)($c['support_phone']??'');$wa=(string)($c['support_whatsapp']??$sp);if($sp||$wa)echo '<p class="muted2">اگر نیاز به پیگیری فوری دارید: '.($sp?'تماس '.e($sp).' ':'').($wa?' · واتساپ '.e($wa):'').'</p>';echo '</div></main>';foot();exit;}

