button class="btn lime sm" name="decision" value="approve">تأیید</button><button class="btn light sm" name="decision" value="reject">رد</button></form></td></tr>';}echo '</table></div></section><section class="fcard"><h2>گزارش مغایرت مشتریان</h2><div class="ftable"><table><tr><th>مشتری</th><th>مبلغ ثبت‌شده</th><th>مبلغ اعلامی مشتری</th><th>توضیح</th><th>زمان</th></tr>';foreach(array_reverse($feedback) as $f)if(($f['answer']??'')==='dispute'){$p=null;foreach($payments as $x)if((string)$x['id']===(string)$f['payment_id']){$p=$x;break;}$l=$p?lead((string)$p['lead_id']):null;echo '<tr><td>'.e((string)($l['business']??$l['name']??'-')).'</td><td>'.number_format((int)($p['amount']??0)).'</td><td>'.number_format((int)($f['actual_amount']??0)).'</td><td>'.e((string)($f['note']??'')).'</td><td>'.e((string)$f['created_at']).'</td></tr>';}echo '</table></div></section>';
}else{$s=summary($bid);$won=array_values(array_filter(j(A),fn($x)=>(string)($x['branch_id']??'')===$bid&&($x['status']??'')==='won'));$payments=array_values(array_filter(j(P),fn($x)=>(string)($x['branch_id']??'')===$bid&&($x['status']??'active')!=='void'));$rems=array_values(array_filter(j(M),fn($x)=>(string)($x['branch_id']??'')===$bid));echo '<div class="finstats"><div><span>کل دریافتی مشتری</span><b>'.number_format($s['gross']).' تومان</b></div><div><span>سهم/درآمد شما</span><b>'.number_format($s['branch_share']).' تومان</b></div><div><span>سهم شرکت</span><b>'.number_format($s['company_share']).' تومان</b></div><div><span>باید به شرکت واریز کنید</span><b>'.number_format($s['due']).' تومان</b></div></div><div class="fgrid"><section class="fcard"><h2>ثبت دریافت جدید از مشتری</h2><form method="post" class="form">'.cf().'<input type="hidden" name="action" value="add_payment"><label>سفارش قطعی<select name="assignment_id" required><option value="">انتخاب کنید</option>';foreach($won as $a){$l=lead((string)$a['lead_id']);echo '<option value="'.e((string)$a['id']).'">'.e((string)($l['business']??$l['name']??'مشتری')).' · پورسانت '.pctFor($a).'%</option>';}echo '</select></label><label>مبلغ دریافتی (تومان)<input inputmode="numeric" name="amount" required></label><label>بابت چه چیزی؟<select name="purpose" required><option>بیعانه</option><option>قسط پروژه</option><option>سئو</option><option>پیامک</option><option>پشتیبانی</option><option>دامنه و هاست</option><option>خدمت اضافه</option><option>سایر</option></select></label><label>توضیح دقیق<input name="description" placeholder="مثلاً قسط دوم طراحی فروشگاه"></label><button class="btn lime">ثبت دریافت و محاسبه سهم‌ها</button></form></section><section class="fcard"><h2>ثبت واریزی به شرکت</h2><p class="muted2">واریزی تا زمان تأیید مدیریت از بدهی شما کسر نمی‌شود.</p><form method="post" enctype="multipart/form-data" class="form">'.cf().'<input type="hidden" name="action" value="add_remittance"><label>مبلغ واریزی<input inputmode="numeric" name="amount" required></label><label>کد/شماره پیگیری<input name="tracking_code" required></label><label>تصویر رسید یا PDF<input type="file" name="receipt" accept="image/*,.pdf"></label><button class="btn dark">ارسال برای تأیید مدیریت</button></form><p>در انتظار تأیید: <b>'.number_format($s['pending']).' تومان</b></p></section></div><section class="fcard"><h2>ریز دریافتی‌های مشتری</h2><div class="ftable"><table><tr><th>مشتری</th><th>بابت</th><th>مبلغ</th><th>درصد شما</th><th>سهم شما</th><th>سهم شرکت</th><th>تأیید مشتری</th><th>زمان</th></tr>';foreach(array_reverse($payments) as $p){$l=lead((string)$p['lead_id']);$cs=(string)($p['customer_status']??'pending');echo '<tr><td>'.e((string)($l['business']??$l['name']??'-')).'</td><td>'.e((string)$p['purpose']).'</td><td>'.number_format((int)$p['amount']).'</td><td>'.(int)$p['commission_percent'].'%</td><td>'.number_format((int)$p['branch_share']).'</td><td>'.number_format((int)$p['company_share']).'</td><td><span class="status '.($cs==='disputed'?'bad2':($cs==='ok'?'ok2':'warn2')).'">'.($cs==='disputed'?'مغایرت':($cs==='ok'?'تأیید شده':'منتظر پاسخ')).'</span></td><td>'.e((string)$p['created_at']).'</td></tr>';}echo '</table></div></section><section class="fcard"><h2>سوابق واریزی به شرکت</h2><div class="ftable"><table><tr><th>مبلغ</th><th>کد پیگیری</th><th>وضعیت</th><th>زمان ثبت</th><th>زمان بررسی</th></tr>';foreach(array_reverse($rems) as $r){$st=(string)($r['status']??'pending');echo '<tr><td>'.number_format((int)$r['amount']).'</td><td>'.e((string)$r['tracking_code']).'</td><td><span class="status '.($st==='approved'?'ok2':($st==='rejected'?'bad2':'warn2')).'">'.($st==='approved'?'تأیید شده':($st==='rejected'?'رد شده':'در انتظار')).'</span></td><td>'.e((string)$r['created_at']).'</td><td>'.e((string)($r['reviewed_at']??'')).'</td></tr>';}echo '</table></div></section>';}
